class Solution:
    def fewestCoins(self, coins: List[int], amount: int) -> int:
        INF = amount + 1  # more coins than any real answer can need
        fewest = [0] + [INF] * amount
        for a in range(1, amount + 1):
            for c in coins:
                if c <= a and fewest[a - c] + 1 < fewest[a]:
                    fewest[a] = fewest[a - c] + 1
        return -1 if fewest[amount] == INF else fewest[amount]

